// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // the test contract is msg.sender at deployment, hence c's admin
        bool ok = true;
        bool ret = false;
        try c.setOwner(newOwner) returns (bool success) {
            ret = success;
        } catch {
            ok = false;
        }
        assertTrue(!ok || (ret && c.owner() == newOwner));
    }
}
